\set ON_ERROR_STOP on
create or replace function pg_temp.assert_zero(value bigint,message text) returns void language plpgsql as $$begin if value<>0 then raise exception 'ASSERTION_FAILED: % (%)',message,value;end if;end$$;
select pg_temp.assert_zero((select count(*) from phase35_rehearsal.tables b left join pg_class c on c.relname=b.table_name and c.relnamespace='public'::regnamespace and c.relkind in ('r','p') where c.oid is null),'baseline tables removed');
select pg_temp.assert_zero((select count(*) from phase35_rehearsal.columns b left join information_schema.columns c on c.table_schema='public' and c.table_name=b.table_name and c.column_name=b.column_name where c.column_name is null or row(c.ordinal_position,c.data_type,c.udt_name,c.is_nullable,coalesce(c.column_default,'')) is distinct from row(b.ordinal_position,b.data_type,b.udt_name,b.is_nullable,coalesce(b.column_default,''))),'baseline columns changed');
select pg_temp.assert_zero((select count(*) from phase35_rehearsal.constraints b left join pg_constraint c on c.conname=b.conname and c.conrelid=(quote_ident(b.schema_name)||'.'||quote_ident(b.table_name))::regclass where c.oid is null or pg_get_constraintdef(c.oid,true)<>b.definition),'baseline constraints changed');
select pg_temp.assert_zero((select count(*) from phase35_rehearsal.policies b left join pg_policies p on p.schemaname=b.schemaname and p.tablename=b.tablename and p.policyname=b.policyname where p.policyname is null or row(p.permissive,p.roles,p.cmd,coalesce(p.qual,''),coalesce(p.with_check,'')) is distinct from row(b.permissive,b.roles,b.cmd,coalesce(b.qual,''),coalesce(b.with_check,''))),'baseline policies changed');
select pg_temp.assert_zero((select count(*) from phase35_rehearsal.grants b left join information_schema.role_table_grants g on row(g.grantor,g.grantee,g.table_schema,g.table_name,g.privilege_type,g.is_grantable)=row(b.grantor,b.grantee,b.table_schema,b.table_name,b.privilege_type,b.is_grantable) where g.table_name is null),'baseline grants removed');
select pg_temp.assert_zero((select count(*) from phase35_rehearsal.functions b left join pg_proc p on p.proname=b.proname and pg_get_function_identity_arguments(p.oid)=b.arguments and p.pronamespace='public'::regnamespace where p.oid is null or pg_get_functiondef(p.oid)<>b.definition),'baseline functions changed');
select pg_temp.assert_zero((select count(*) from phase35_rehearsal.triggers b left join pg_trigger t on t.tgname=b.tgname and t.tgrelid=('public.'||quote_ident(b.table_name))::regclass where t.oid is null or pg_get_triggerdef(t.oid,true)<>b.definition),'baseline triggers changed');
select pg_temp.assert_zero((select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and c.relname in ('role_permissions','user_permission_overrides','account_invitations','offers','offer_events','payment_events','ledger_entries') and not c.relrowsecurity),'new RLS tables without RLS');
select (select count(*) from phase35_rehearsal.tables) baseline_tables,(select count(*) from pg_tables where schemaname='public') post_migration_tables;
select 'phase35_inventory_preservation' test_suite,'PASS' result;

